  "SEGMENTS.consultant.features.4.title": "Egészségpontszám — magyarázattal",
  "SEGMENTS.consultant.features.4.body": "Megmutatja, hogyan áll össze a pontszám; ha hiányzik a bemeneti adat, a súlyok újranormalizálódnak, nem ad kitalált számot.",
  "SEGMENTS.consultant.features.5.title": "Megosztó link",
